package com.gameaggregator.tenantservice.domain; import com.gameaggregator.platform.core.common.persistence.BaseEntity; import jakarta.persistence.*; import java.util.*; @Entity @Table(name="roles",uniqueConstraints=@UniqueConstraint(columnNames={"tenant_id","code"})) public class Role extends BaseEntity { @Column(name="tenant_id",nullable=false) private UUID tenantId; @Column(nullable=false,length=100) private String code; @Column(nullable=false,length=150) private String name; @ManyToMany(fetch=FetchType.EAGER) @JoinTable(name="role_permissions",joinColumns=@JoinColumn(name="role_id"),inverseJoinColumns=@JoinColumn(name="permission_id")) private Set<Permission> permissions=new HashSet<>(); protected Role(){} public Role(UUID tenantId,String code,String name){this.tenantId=tenantId;this.code=code;this.name=name;} public UUID getTenantId(){return tenantId;} public String getCode(){return code;} public String getName(){return name;} public Set<Permission> getPermissions(){return Set.copyOf(permissions);} public void addPermission(Permission permission){permissions.add(permission);} }
